#!/bin/bash
# GENERATED by ~/.config/session/niri2mango from ~/.config/niri. Do not edit; edit niri and re-run.
# Runs once when mango starts (mango-session also imports the env into systemd).
# skipped (niri-only): "~/.config/niri/scripts/scratchpad" "watch"
(oq omarchy-launch-shell) >/dev/null 2>&1 &
systemctl --user import-environment WAYLAND_DISPLAY DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE
dbus-update-activation-environment --systemd WAYLAND_DISPLAY DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE
(/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1) >/dev/null 2>&1 &
(fcitx5 -dr) >/dev/null 2>&1 &
(export $(gnome-keyring-daemon --start --components=pkcs11,secrets,ssh)) >/dev/null 2>&1 &
(wl-clip-persist --clipboard regular) >/dev/null 2>&1 &
(wl-paste --watch cliphist store) >/dev/null 2>&1 &
(~/.config/session/init.sh) >/dev/null 2>&1 &
# graphical-session.target can't be started by hand: start the units wanted by it (after the shell is up).
(sleep 2; for u in ~/.config/systemd/user/graphical-session.target.wants/*; do
  systemctl --user start "$(basename "$u")" &
done) >/dev/null 2>&1 &
(sleep 3; rembrowser --background) >/dev/null 2>&1 &
